SELECT  FROM profile_memory_items item
WHERE item.user_id = #{userId}
  AND item.status IN ('ACTIVE', 'CONFLICTED', 'CONFIRMED')
  AND (item.valid_until IS NULL OR item.valid_until > NOW())
  AND EXISTS (
      SELECT 1 FROM memories memory
      WHERE memory.id = item.memory_id
        AND memory.user_id = #{userId}
        AND memory.memory_type = 'USER_PROFILE'
        AND memory.sharing_scope = 'USER_AGENTS'
        AND memory.status = 'VISIBLE'
  )
  AND (
      item.source_agent_id = #{agentId}
      OR EXISTS (
          SELECT 1 FROM profile_memory_grants grant_row
          WHERE grant_row.user_id = item.user_id
            AND grant_row.agent_id = #{agentId}
            AND (grant_row.namespace = '*' OR grant_row.namespace = item.namespace)
      )
  )
ORDER BY namespace, fact_key, updated_at DESC

